svg.script:
(function(){
  const ids = ['teacherFull','engineerFull','playgroundFull','classroomFull','familyFull'];
  ids.forEach(function(id){
    const el = document.getElementById(id);
    if(!el) return;

    el.addEventListener('pointerdown', function(){
      // استجابة سريعة للطالب مع بقاء الصورة طبقة واحدة
      el.style.animationPlayState = 'paused';
      el.animate([
        { transform: getComputedStyle(el).transform },
        { transform: 'scale(1.035) rotate(0.8deg)' },
        { transform: 'scale(0.992) rotate(-0.55deg)' },
        { transform: 'scale(1.015) rotate(0deg)' }
      ], {
        duration: 360,
        easing: 'cubic-bezier(.22,.8,.3,1)'
      }).onfinish = function(){
        el.style.animationPlayState = 'running';
      };
    });
  });
})();
